二、核心观点拆解
观点1：个体是社会的产物，理解社会才能理解自己。作者指出，很多人将社会领域的成败归因于天赋或机缘，实则有其可学习、可优化的方法论，多数问题并非能力不足，而是认知与实践不到位。

